-- WLF 2.0.0: run once in a NEW Supabase project. No existing Apps Script data is changed.
begin;
create schema if not exists wlf_private;
revoke all on schema wlf_private from public, anon;
grant usage on schema wlf_private to authenticated;
create table public.wlf_profiles (
 id uuid primary key references auth.users(id) on delete cascade,
 email text not null unique, name text not null,
 role text not null default 'User' check(role in ('Super Admin','Admin','R&I','User')),
 status text not null default 'Pending' check(status in ('Pending','Approved','Rejected')),
 permissions text[] not null default '{}', access_revision integer not null default 0,
 created_at timestamptz not null default now()
);
create table public.wlf_components(id bigint generated by default as identity primary key, values jsonb not null check(jsonb_typeof(values)='array'), revision integer not null default 1);
create table public.wlf_settings(key text primary key, value jsonb not null);
create table public.wlf_troubleshooting(id text primary key, controller text not null, option_key text not null, content jsonb not null, revision integer not null default 1, deleted boolean not null default false);
create unique index wlf_trouble_key_idx on public.wlf_troubleshooting(controller,option_key) where not deleted;
create table public.wlf_forms(category text primary key check(category in ('commissioning','aftersales')), schema jsonb not null, revision integer not null default 1);
create table public.wlf_requests(
 id uuid primary key default gen_random_uuid(), category text not null references public.wlf_forms(category),
 status text not null default 'Pending' check(status in ('Pending','Received','Forwarded','Not Solved','Solved')),
 created_by uuid not null references public.wlf_profiles(id), assigned_to uuid references public.wlf_profiles(id),
 created_at timestamptz not null default now(), updated_at timestamptz not null default now(), revision integer not null default 1,
 values jsonb not null, form_schema jsonb not null, reference text not null,
 solution text not null default '', solved_by uuid references public.wlf_profiles(id), solved_at timestamptz,
 not_solved_by uuid references public.wlf_profiles(id), not_solved_at timestamptz, deleted_at timestamptz,
 search_text text not null default ''
);
create table public.wlf_history(id bigint generated always as identity primary key, request_id uuid not null references public.wlf_requests(id), actor uuid not null references public.wlf_profiles(id), action text not null, comment text not null default '', to_user uuid references public.wlf_profiles(id), at timestamptz not null default now());
create table public.wlf_operations(actor uuid not null references public.wlf_profiles(id), mutation_id text not null, action text not null, request_id uuid references public.wlf_requests(id), payload jsonb not null, primary key(actor,mutation_id));
create table public.wlf_records(id uuid primary key, owner uuid not null references public.wlf_profiles(id), record jsonb not null, at timestamptz not null default now());
create table public.wlf_usage(id bigint generated always as identity primary key, actor uuid not null references public.wlf_profiles(id), action text not null, details text not null default '', at timestamptz not null default now());
create index wlf_requests_owner_idx on public.wlf_requests(created_by,updated_at desc) where deleted_at is null;
create index wlf_requests_team_status_idx on public.wlf_requests(category,status,updated_at desc) where deleted_at is null;
create index wlf_requests_assignee_idx on public.wlf_requests(assigned_to,updated_at desc) where deleted_at is null;
create index wlf_requests_solver_idx on public.wlf_requests(solved_by,solved_at desc) where deleted_at is null;
create index wlf_history_request_idx on public.wlf_history(request_id,at);
create index wlf_history_actor_idx on public.wlf_history(actor,request_id);
create index wlf_usage_actor_idx on public.wlf_usage(actor,at desc);
create index wlf_records_owner_idx on public.wlf_records(owner);
-- All privilege helpers verify the current Auth identity; role is never taken from user_metadata.
create function wlf_private.me() returns public.wlf_profiles language sql stable security definer set search_path='' as $$select p from public.wlf_profiles p where p.id=auth.uid()$$;
create function wlf_private.approved() returns boolean language sql stable security definer set search_path='' as $$select coalesce((select p.status='Approved' from public.wlf_profiles p where p.id=auth.uid()),false)$$;
create function wlf_private.super() returns boolean language sql stable security definer set search_path='' as $$select coalesce((select p.status='Approved' and p.role='Super Admin' from public.wlf_profiles p where p.id=auth.uid()),false)$$;
create function wlf_private.can(k text) returns boolean language sql stable security definer set search_path='' as $$select coalesce((select p.status='Approved' and (p.role<>'User' or k=any(p.permissions)) from public.wlf_profiles p where p.id=auth.uid()),false)$$;
create function wlf_private.team(c text) returns boolean language sql stable security definer set search_path='' as $$select wlf_private.can('support:'||c||':request')$$;
create function wlf_private.visible(c text,owner uuid) returns boolean language sql stable security definer set search_path='' as $$select wlf_private.team(c) and ((wlf_private.me()).role<>'User' or owner=auth.uid())$$;
create function wlf_private.safe_user(p public.wlf_profiles) returns jsonb language sql immutable set search_path='' as $$select jsonb_build_object('email',p.email,'name',p.name,'role',p.role,'status',p.status,'permissions',p.permissions,'accessRevision',p.access_revision)$$;
create function wlf_private.directory() returns jsonb language sql stable security definer set search_path='' as $$select coalesce(jsonb_agg(jsonb_build_object('email',p.email,'name',p.name,'role',p.role,'status',p.status) order by p.name),'[]') from public.wlf_profiles p where p.status='Approved' and p.role='R&I' and wlf_private.approved()$$;
-- Full user management rows are visible ONLY to Super Admin; everyone can see their own profile.
alter table public.wlf_profiles enable row level security;
create policy wlf_profile_read on public.wlf_profiles for select to authenticated using(id=(select auth.uid()) or (select wlf_private.super()));
alter table public.wlf_components enable row level security;
create policy wlf_components_read on public.wlf_components for select to authenticated using((select wlf_private.can('selection')) or (select wlf_private.can('calc:energy')) or (select wlf_private.can('calc:solar')));
alter table public.wlf_settings enable row level security;
create policy wlf_settings_read on public.wlf_settings for select to authenticated using((select wlf_private.approved()));
alter table public.wlf_troubleshooting enable row level security;
create policy wlf_trouble_read on public.wlf_troubleshooting for select to authenticated using(not deleted and wlf_private.can(case when controller='GENERAL' then 'tb:general:'||id when content->>'kind'='procedure' then 'tb:option:'||id else 'tb:'||controller||':error' end));
alter table public.wlf_forms enable row level security;
create policy wlf_forms_read on public.wlf_forms for select to authenticated using(wlf_private.team(category));
alter table public.wlf_requests enable row level security;
create policy wlf_requests_read on public.wlf_requests for select to authenticated using(deleted_at is null and wlf_private.visible(category,created_by));
alter table public.wlf_history enable row level security;
create policy wlf_history_read on public.wlf_history for select to authenticated using(exists(select 1 from public.wlf_requests r where r.id=request_id and r.deleted_at is null and wlf_private.visible(r.category,r.created_by)));
alter table public.wlf_operations enable row level security;
alter table public.wlf_records enable row level security;
create policy wlf_records_read on public.wlf_records for select to authenticated using(owner=(select auth.uid()) and (select wlf_private.approved()));
alter table public.wlf_usage enable row level security;
create policy wlf_usage_read on public.wlf_usage for select to authenticated using((select wlf_private.can('dashboard')) and ((wlf_private.me()).role<>'User' or actor=(select auth.uid())));
revoke all on all tables in schema public from anon,authenticated;
grant select on public.wlf_profiles,public.wlf_components,public.wlf_settings,public.wlf_troubleshooting,public.wlf_forms,public.wlf_requests,public.wlf_history,public.wlf_records,public.wlf_usage to authenticated;
-- Pending identity created by Supabase Auth. Metadata may set display name, never role/status.
create function wlf_private.new_user() returns trigger language plpgsql security definer set search_path='' as $$begin
 insert into public.wlf_profiles(id,email,name) values(new.id,lower(new.email),left(coalesce(nullif(new.raw_user_meta_data->>'name',''),split_part(new.email,'@',1)),120));return new;end$$;
create trigger wlf_on_auth_user after insert on auth.users for each row execute function wlf_private.new_user();
-- Realtime table events are scoped by SELECT RLS. No public broadcast leaks.
do $$begin
 if exists(select 1 from pg_publication where pubname='supabase_realtime') then
 alter publication supabase_realtime add table public.wlf_requests,public.wlf_profiles,public.wlf_components,public.wlf_troubleshooting,public.wlf_forms;
 end if;
end$$;
commit;
